// Lee el mensaje, recorta el historial y aplica límites diarios (por IP y total).
const req = $input.first().json;
let body = req.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = {}; } }
body = body || {};
const mensaje = String(body.mensaje || '').trim().slice(0, 200);
const historial = Array.isArray(body.historial) ? body.historial.slice(-4) : [];
const h = req.headers || {};
const ip = String(h['cf-connecting-ip'] || h['x-real-ip'] || String(h['x-forwarded-for'] || '').split(',')[0] || 'desconocida').trim();

const LIMITE_POR_IP = 20;     // preguntas a la IA por visitante al día
const LIMITE_TOTAL = 300;     // preguntas a la IA en total al día
const dia = new Date().toISOString().slice(0, 10);
const st = $getWorkflowStaticData('global');
if (st.dia !== dia) { st.dia = dia; st.total = 0; st.ips = {}; }
const usadas = st.ips[ip] || 0;

if (!mensaje) return [{ json: { bloqueado: true, motivo: 'vacio' } }];
if (usadas >= LIMITE_POR_IP || st.total >= LIMITE_TOTAL) return [{ json: { bloqueado: true, motivo: 'limite' } }];
st.ips[ip] = usadas + 1;
st.total += 1;

const SYSTEM = "Eres Sox, el asistente del portafolio web de Daniel Acevedo, desarrollador full stack y de automatización con IA en El Salvador (marca Endanus). Solo hablas de: sus proyectos (Nexo: plataforma web de microservicios con asistentes de IA; Sox: agente de WhatsApp hecho en n8n; Finanzas: gastos por WhatsApp con voz o foto; MVPs en AWS; IA Studio; servidor propio con Docker y n8n), sus servicios (apps web con IA, automatizaciones, reportes, cloud), sus tecnologías y cómo contactarlo. Si preguntan cualquier otra cosa, responde exactamente: Solo puedo ayudarte con el portafolio de Daniel. ¿Te muestro sus proyectos? Responde en español, en máximo 2 frases cortas. No inventes precios, clientes ni datos. Devuelve solo JSON: {\"mensaje\":\"texto\",\"ir_a\":\"pagina o vacío\"}. ir_a solo puede ser: inicio.html, portafolio.html, servicios.html, contacto.html, sobremi.html, stack.html, casos.html, clientes.html.";
const messages = [{ role: 'system', content: SYSTEM }];
for (const m of historial) {
  const texto = String((m && m.texto) || '').slice(0, 200);
  if (texto) messages.push({ role: m.rol === 'usuario' ? 'user' : 'assistant', content: texto });
}
messages.push({ role: 'user', content: mensaje });

return [{ json: {
  bloqueado: false,
  payload: { model: 'gpt-4o-mini', temperature: 0.3, max_tokens: 120, response_format: { type: 'json_object' }, messages }
} }];

const m = $input.first().json.motivo;
return [{ json: {
  mensaje: m === 'limite'
    ? 'Por hoy ya respondí muchas preguntas. Te puedo llevar a Proyectos, Servicios o Contacto con los botones.'
    : '¿Qué te gustaría ver del portafolio de Daniel?',
  ir_a: ''
} }];

// Toma la respuesta del modelo, valida la página y deja un mensaje seguro si algo falla.
const PAGINAS = ['inicio.html','portafolio.html','servicios.html','contacto.html','sobremi.html','stack.html','casos.html','clientes.html'];
const r = $input.first().json || {};
let out = { mensaje: 'Ahora no pude responder eso, pero te puedo llevar a Proyectos, Servicios o Contacto.', ir_a: '' };
try {
  const txt = r.choices && r.choices[0] && r.choices[0].message && r.choices[0].message.content;
  const d = JSON.parse(txt || '{}');
  if (typeof d.mensaje === 'string' && d.mensaje.trim()) out.mensaje = d.mensaje.trim().slice(0, 400);
  const ir = typeof d.ir_a === 'string' ? d.ir_a.trim().toLowerCase() : '';
  out.ir_a = PAGINAS.includes(ir) ? ir : '';
} catch (e) { /* se queda el mensaje seguro */ }
return [{ json: out }];
